-- Progressive login lockout. Keys are HMAC-SHA256 values generated by the Edge Function.
-- Five invalid passwords trigger a 5-minute lock. Every subsequent lockout
-- increases by another 5 minutes (10, 15, 20...), until a successful login resets it.

create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
grant usage on schema private to service_role;

create table if not exists private.auth_login_lockouts (
  identifier_key text primary key,
  failed_attempts integer not null default 0 check (failed_attempts >= 0),
  lock_level integer not null default 0 check (lock_level >= 0),
  locked_until timestamptz,
  updated_at timestamptz not null default now()
);

alter table private.auth_login_lockouts enable row level security;
revoke all on private.auth_login_lockouts from public, anon, authenticated;
grant all on private.auth_login_lockouts to service_role;

create or replace function public.auth_login_lock_check(p_identifier text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_locked_until timestamptz;
begin
  if p_identifier is null or length(p_identifier) <> 64 then
    return jsonb_build_object('allowed', false, 'seconds_remaining', 1);
  end if;

  select l.locked_until
    into v_locked_until
    from private.auth_login_lockouts l
   where l.identifier_key = p_identifier;

  if v_locked_until is not null and v_locked_until > now() then
    return jsonb_build_object(
      'allowed', false,
      'seconds_remaining', greatest(1, ceil(extract(epoch from (v_locked_until - now())))::integer)
    );
  end if;

  return jsonb_build_object('allowed', true, 'seconds_remaining', 0);
end;
$$;

create or replace function public.auth_login_lock_failure(p_identifier text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row private.auth_login_lockouts%rowtype;
  v_attempts integer;
  v_level integer;
  v_duration integer;
  v_now timestamptz := now();
begin
  if p_identifier is null or length(p_identifier) <> 64 then
    return jsonb_build_object('lock_seconds', 0, 'error', 'invalid_identifier');
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_identifier, 0));

  select *
    into v_row
    from private.auth_login_lockouts
   where identifier_key = p_identifier
   for update;

  if not found then
    insert into private.auth_login_lockouts(identifier_key, failed_attempts, lock_level, updated_at)
    values (p_identifier, 1, 0, v_now);
    return jsonb_build_object('failed_attempts', 1, 'lock_seconds', 0, 'lock_level', 0);
  end if;

  if v_row.locked_until is not null and v_row.locked_until > v_now then
    return jsonb_build_object(
      'failed_attempts', v_row.failed_attempts,
      'lock_seconds', greatest(1, ceil(extract(epoch from (v_row.locked_until - v_now)))::integer),
      'lock_level', v_row.lock_level
    );
  end if;

  v_attempts := coalesce(v_row.failed_attempts, 0) + 1;
  v_level := coalesce(v_row.lock_level, 0);

  if v_attempts >= 5 then
    v_level := v_level + 1;
    v_duration := v_level * 5 * 60;
    update private.auth_login_lockouts
       set failed_attempts = 0,
           lock_level = v_level,
           locked_until = v_now + make_interval(secs => v_duration),
           updated_at = v_now
     where identifier_key = p_identifier;

    return jsonb_build_object(
      'failed_attempts', 0,
      'lock_seconds', v_duration,
      'lock_level', v_level
    );
  end if;

  update private.auth_login_lockouts
     set failed_attempts = v_attempts,
         locked_until = null,
         updated_at = v_now
   where identifier_key = p_identifier;

  return jsonb_build_object('failed_attempts', v_attempts, 'lock_seconds', 0, 'lock_level', v_level);
end;
$$;

create or replace function public.auth_login_lock_success(p_identifier text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_identifier is null or length(p_identifier) <> 64 then
    return jsonb_build_object('success', false);
  end if;

  delete from private.auth_login_lockouts
   where identifier_key = p_identifier;

  return jsonb_build_object('success', true);
end;
$$;

revoke execute on function public.auth_login_lock_check(text) from public, anon, authenticated;
revoke execute on function public.auth_login_lock_failure(text) from public, anon, authenticated;
revoke execute on function public.auth_login_lock_success(text) from public, anon, authenticated;
grant execute on function public.auth_login_lock_check(text) to service_role;
grant execute on function public.auth_login_lock_failure(text) to service_role;
grant execute on function public.auth_login_lock_success(text) to service_role;
